def fibonacci(n):
  if n <= 0:
    return "Error"
  elif n == 1:
    return 1
  else:
    fib_series = [0, 1]
    for i in range(2, n+1):
      fib_series.append(fib_series[i-1] + fib_series[i-2])
    return fib_series[n-1]

