public class Main {
    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        System.out.println(Arrays.deepToString(generatePermutations(nums)));
    }

    public static int[][] generatePermutations(int[] nums) {
        int n = nums.length;
        int[][] output = new int[factorial(n)][n];
        backtrack(nums, 0, n, output);
        return output;
    }

    public static void backtrack(int[] nums, int first, int n, int[][] output) {
        if (first == n) {
            output[permIndex++] = nums.clone();
        }
        for (int i = first; i < n; i++) {
            swap(nums, first, i);
            backtrack(nums, first + 1, n, output);
            swap(nums, first, i);
        }
    }

    public static void swap(int[] nums, int i, int j) {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }

    public static int factorial(int n) {
        int result = 1;
        for (int i = 1; i <= n; i++) {
            result *= i;
        }
        return result;
    }
}

